"""Compare two pip-compile lock files ignoring autogenerated header.

Phase 3 Step 3.2: ``lock-integrity`` CI job needs to verify that a
freshly regenerated lock matches the committed one. ``git diff
--exit-code`` does not work directly because pip-compile embeds the
``--output-file`` path (and, for layered locks, the ``--constraint``
path) into a header comment. When CI regenerates into ``tmp/``, the
header differs but the package list / hashes — the bytes that
control supply-chain — should be identical.

This script strips the autogenerated header (lines starting with ``#``
before the first non-comment, non-blank line) and compares the
remaining body byte-for-byte. Differences are printed in unified-diff
form and the script exits non-zero. If bodies match, exit 0 silently.

Usage::

    python tools/diff_locks.py <committed-lock> <regenerated-lock>

The script is intentionally tiny and has no third-party dependencies;
it runs under any Python that qgb's CI ships (3.10+).
"""

from __future__ import annotations

import difflib
import sys
from pathlib import Path


def _normalize_newlines(text: str) -> str:
    """Collapse CRLF / CR into LF so the comparison is OS-independent.

    git's autocrlf and pip-compile's host-dependent line endings can both
    introduce CRLF on Windows. The `.gitattributes` rule for `requirements*.lock`
    pins line endings to LF in the repo, but defending here as well makes
    the diff stable even if a future maintainer's local config bypasses git
    attributes (or runs the script against a lock file outside the repo).
    """
    return text.replace("\r\n", "\n").replace("\r", "\n")


def strip_header(text: str) -> str:
    """Drop leading comment block (the pip-compile autogenerated header).

    Returns the body starting at the first non-comment, non-blank line.
    Line endings are normalized to LF before stripping so CRLF / LF
    differences do not cause spurious diffs.
    """
    lines = _normalize_newlines(text).splitlines(keepends=True)
    body_start = 0
    for i, line in enumerate(lines):
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("#"):
            continue
        body_start = i
        break
    return "".join(lines[body_start:])


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(
            f"usage: {argv[0]} <committed-lock> <regenerated-lock>",
            file=sys.stderr,
        )
        return 2
    committed = Path(argv[1])
    regenerated = Path(argv[2])
    a = strip_header(committed.read_text(encoding="utf-8-sig"))
    b = strip_header(regenerated.read_text(encoding="utf-8-sig"))
    if a == b:
        return 0
    diff = difflib.unified_diff(
        a.splitlines(keepends=True),
        b.splitlines(keepends=True),
        fromfile=str(committed),
        tofile=str(regenerated),
    )
    sys.stdout.writelines(diff)
    print(
        f"\nLock body mismatch: {committed} vs {regenerated}. "
        "Regenerate per SECURITY.md and commit.",
        file=sys.stderr,
    )
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
